        mustNonEmptyString(data.model, 'model（实际拉起的档位）');
        // 用 hasOwn 只认价目表自己的档位——防「toString」这类原型链上的名字混进账本。
        if (!Object.hasOwn(PRICES.models, data.model)) {
          throw new Error(`model（实际拉起的档位）「${data.model}」不在价目表内，对不了账`);
        }
      }
    }
  },
  // 复盘记录（里程碑验收失败后重拆 sprint 之前必须先复盘）
  'review': {
    path: (seq) => PATHS.review(seq),
    mode: 'overwrite',
    validate(data) {
      mustObject(data, '复盘记录');
    }
  },
  // 验收结论：追加进对应里程碑的 verdicts[]，状态流转由脚本读结论触发
  'verdict': {
    path: () => 'phase1/milestones.json',
    mode: 'append-item',
    validate(data) {
      mustObject(data, '验收结论');
      mustNonEmptyString(data.milestone, 'milestone（验收哪个里程碑）');
      if (typeof data.pass !== 'boolean') throw new Error('pass（验收过没过）必须是 true 或 false');
    }
  },
  // 评审证据（G 项）：评审员试图证伪本 sprint 时做了什么、看到了什么，
  // advance sprint→done 的结构前提（见 statemachine：done 前至少要有一条，不论 verdict——
  // reject 的证据同样算「评审过」，是否要打回重来归 precheck/审计裁，这道闸只问「评审过没有」）。
  // 落点与 sprint-rework 一致：追加进同一份 sprints/<id>.json 的 reviews[]（append-item）。
  'review-evidence': {
    path: (id) => `sprints/${id}.json`,
    mode: 'append-item',
    validate(data, id) {
      mustObject(data, '评审证据');
      mustNonEmptyString(data.sprint, 'sprint（证据针对哪个 sprint）');
      if (data.sprint !== id) {
        throw new Error(`评审证据的 --id「${id}」与 data.sprint「${data.sprint}」不一致，写错档案了`);
      }
      mustNonEmptyString(data.who, 'who（评审人）');
      if (data.verdict !== 'pass' && data.verdict !== 'reject') {
        throw new Error('verdict（评审结论）只能是 pass（通过）或 reject（打回）');
      }
      mustNonEmptyString(data.tried, 'tried（试图证伪时做了什么，如起服务/跑测试/边界穿刺）');
      mustNonEmptyString(data.evidence, 'evidence（关键观察，允许引用文件路径）');
      mustInteger(data.at_tick, 'at_tick（发生在第几轮）');
    }
  }
};

