1	import { test, expect, type Page } from '@playwright/test';
2	
3	// 念念 · 陈列室 —— U1-S2 存储换血 e2e（对齐 sprint【验收硬指标】/ criteria）。
4	//
5	// 只覆盖 U1-S2 goal 点名的两块收口，逐条对齐 sprint 验收：
6	//   ① 终结 saveState 静默失败：人为让底层写入（localStorage.setItem）抛错（配额超限 / 隐私模式），
7	//      错误能冒泡到上层并被界面感知（弹明确提示），不出现「提示成功、刷新就没」的静默丢失；应用不崩。
8	//   ② 照片二进制入 IndexedDB、LocalStorage 只存引用：带内联图片（data: base64）的用户物件落盘后，
9	//      二进制写进 IndexedDB，LocalStorage 序列化内容里查不到该图片的二进制 / base64（只留 imageRef）。
10	//
11	// 边界：用户上传 UI、渲染层据 imageRef 取图 hydrate 属 U2/U3；本文件只验存储层的换血与错误冒泡。
12	
13	const STORAGE_KEY = 'memories.gallery';
14	const IMAGE_DB = 'memories.images';
15	const IMAGE_STORE = 'images';
16	
17	// 一张可辨识的 1×1 透明 PNG data URL；其 base64 体用于在 LocalStorage 里做「查不到」断言。
18	const PNG_1PX =
19	  'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==';
20	const PNG_BASE64_BODY = PNG_1PX.split(',')[1];
21	
22	const USER_ITEM_ID = 'user-photo-1';
23	const EXPECTED_REF = `img-${USER_ITEM_ID}`;
24	
25	/** 读回 localStorage 里整棵状态树（JSON）。 */
26	async function readStore(page: Page): Promise<any> {
27	  return page.evaluate((k) => JSON.parse(localStorage.getItem(k) || 'null'), STORAGE_KEY);
28	}
29	
30	/** 读回 localStorage 里的原始字符串（做「查不到 base64」的子串断言）。 */
31	async function readRaw(page: Page): Promise<string> {
32	  return page.evaluate((k) => localStorage.getItem(k) || '', STORAGE_KEY);
33	}
34	
35	// ============================================================
36	// ① 终结静默失败：写入抛错 → 冒泡 → 界面感知（弹提示），应用不崩
37	// ============================================================
38	test('① 存储写入失败不再静默：setItem 抛错时冒泡到上层、界面弹明确提示，应用不崩', async ({
39	  page,
40	}) => {
41	  const pageErrors: string[] = [];
42	  page.on('pageerror', (e) => pageErrors.push(`pageerror: ${e.message}`));
43	
44	  // 人为让底层写入抛错（模拟配额超限 / 隐私模式）：只对本应用的 key 抛，不误伤其它 setItem。
45	  await page.addInitScript(() => {
46	    const orig = Storage.prototype.setItem;
47	    Storage.prototype.setItem = function (key: string, value: string) {
48	      if (key === 'memories.gallery') {
49	        throw new DOMException('模拟配额超限', 'QuotaExceededError');
50	      }
51	      return orig.call(this, key, value);
52	    };
53	  });
54	
55	  await page.goto('/');
56	
57	  // 应用不崩：外壳照常渲染。
58	  await expect(page.getByTestId('app')).toBeVisible();
59	
60	  // 写入失败被界面感知：明确的失败提示浮现（挂载即触发的首个 saveState 就已失败）。
61	  const banner = page.getByTestId('save-error');
62	  await expect(banner).toBeVisible();
63	  await expect(page.getByTestId('save-error-msg')).toContainText('没能保存');
64	
65	  // 「不是提示成功、刷新就没」：LocalStorage 里确实没有本应用的状态（写入被拒、无声吞不掉数据——用户看得见）。
66	  const raw = await readRaw(page);
67	  expect(raw).toBe('');
68	
69	  // 每一次失败的落盘都被感知：关掉提示后再触发一次状态变更（切游客模式）→ 提示复现。
70	  await page.getByTestId('save-error-dismiss').click();
71	  await expect(banner).toHaveCount(0);
72	
73	  await page.getByTestId('mode-guest').click();
74	  await expect(banner).toBeVisible();
75	  await expect(page.getByTestId('save-error-msg')).toContainText('没能保存');
76	
77	  // 全程无未捕获错误（错误是被 App 捕获并转成提示的，不是抛到 window 崩掉页面）。
78	  expect(pageErrors, `不应出现未捕获错误：\n${pageErrors.join('\n')}`).toEqual([]);
79	});
80	
81	// ============================================================
82	// ② 图片二进制入 IndexedDB、LocalStorage 只存引用（查不到 base64）
83	// ============================================================
84	test('② 内联图片落盘：二进制写进 IndexedDB，LocalStorage 里查不到该图的 base64（只留 imageRef）', async ({
85	  page,
86	}) => {
87	  const pageErrors: string[] = [];
88	  page.on('pageerror', (e) => pageErrors.push(`pageerror: ${e.message}`));
89	
90	  await page.goto('/');
91	  await expect(page.getByTestId('app')).toBeVisible();
92	
93	  // 预置一份 v4 状态：含一件「带内联 data: base64 图片」的用户物件（模拟 U2/U3 上传前的内联形态）。
94	  await page.evaluate(
95	    ({ k, uid, png }) => {
96	      const state = {
97	        schemaVersion: 4,
98	        galleryName: '念念 · 陈列室',
99	        scenes: [],
100	        items: [
101	          {
102	            id: uid,
103	            name: '朋友的照片',
104	            source: 'user',
105	            aspectRatio: 1,
106	            originalImageSrc: png,
107	            displayImageSrc: png,
108	            imageSrc: png,
